#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	// Must be UPROPERTY: a NewObject'd UObject is only kept alive through the
	// reflection system. A raw pointer is invisible to GC and gets purged at
	// the next collect, leaving a dangling pointer (PixelArena-shipping.log:
	// "Collecting garbage: 412 objects purged", then AddPoints access violation).
	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker = nullptr;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "In Source/PixelArena/ArenaGameMode.h, ScoreTracker was a raw C++ pointer (UArenaScoreTracker* ScoreTracker = nullptr) holding a NewObject'd UObject. A raw member is invisible to Unreal's garbage collector, so nothing kept the object alive: the packaged run's GC pass purged it (log line 8, 'LogGarbage: Collecting garbage: 412 objects purged' at 21:05:13), and when a goal was scored 14 s later the stale pointer was dereferenced, producing the fatal access violation reading 0xffffffffffffffff in UArenaScoreTracker::AddPoints() at ArenaScoreTracker.cpp:18, called from AArenaGameMode::OnGoalScored() (log lines 10-14). It only shows up in long packaged sessions because it needs a garbage-collection pass and a scored goal to trigger, while short editor sessions rarely GC. Fixed by declaring the member as UPROPERTY() TObjectPtr<UArenaScoreTracker> so the GC reference graph keeps it alive.",
  "no_colors_cause": "The palette asset /Game/Data/Palettes/DA_Primary is only referenced from C++ via a hardcoded LoadObject path string (ArenaGameMode.cpp:18), which the cooker cannot see as an asset reference, and /Game/Data/Palettes was not listed in any cook list in Config/DefaultGame.ini (only /Game/Data/Effects and the Arena map were). The asset was therefore never cooked into the package: the packaged log shows 'LogStreaming: Error: Couldn't find file for package /Game/Data/Palettes/DA_Primary requested by async loading code' followed by 'Failed to find object' and 'Palette is null, using fallback gray' (log lines 4-6), so the HUD painted everything in fallback gray. It works in the editor because the editor loads assets directly from disk without cooking. Fixed by adding +DirectoriesToAlwaysCook=(Path=\"/Game/Data/Palettes\") to [/Script/UnrealEd.ProjectPackagingSettings] in Config/DefaultGame.ini so the palette is cooked into every package."
}
